interface.definition:
a!localVariables(
  local!extendedColumns: false,
  {
    #"SYSTEM_SYSRULES_checkboxField_v1"(
      value: if(local!extendedColumns, true, null),
      saveInto: a!save(
        local!extendedColumns,
        if(isnull(save!value), false, true)
      ),
      choiceLabels: { "Mostrar detalles adicionales" },
      choiceValues: { true }
    ),
    #"SYSTEM_SYSRULES_gridField_v5"(
      label: "",
      emptyGridMessage: "No se han configurado tipos de trabajo",
      data: #"SYSTEM_SYSRULES_recordData"(
        recordType: #"urn:appian:record-type:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a",
        fields: {
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/name",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxAllowedToStart",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/microbatchSize",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/cancelledCount",
          #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive",
          if(
            local!extendedColumns,
            {
              #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount",
              #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/completedCount"
            },
            {}
          )

        }
      ),
      userFilters: {
        #"urn:appian:user-filter:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/db81ec54-89be-4ebe-8317-8f9f50b55a08"
      },
      showRefreshButton: true(),
      recordActions: {
        #"SYSTEM_SYSRULES_recordActionItem"(
          action: #"urn:appian:record-action:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/bab395fc-ee3d-41ae-a21b-6a349eca9569"
        )
      },
      columns: {
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Estatus",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: #"SYSTEM_SYSRULES_richTextIcon"(
              icon: #"8b6cd839-e057-4c8f-b359-044aa71a5899"(
                isTMEnabled: #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
                isJobTypeActive: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive"]
              ).icon,
              caption: #"8b6cd839-e057-4c8f-b359-044aa71a5899"(
                isTMEnabled: #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
                isJobTypeActive: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive"]
              ).caption,
              size: "MEDIUM",
              color: #"8b6cd839-e057-4c8f-b359-044aa71a5899"(
                isTMEnabled: #"_a-0000e3b9-9c60-8000-8592-01ef9001ef90_105014",
                isJobTypeActive: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/isActive"]
              ).color
            )
          ),
          align: "CENTER"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Tipo de trabajo",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: {
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/name"],
                link: #"SYSTEM_SYSRULES_recordLink"(
                  recordType: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107107",
                  identifier: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/id"],
                  showWhen: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106893"()
                ),
                style: "STRONG",
                linkStyle: "STANDALONE"
              ),
              #"SYSTEM_SYSRULES_richTextItem_v1"(
                text: {
                  "  ",
                  #"SYSTEM_SYSRULES_richTextIcon"(
                    icon: "layer-group",
                    caption: "Modo microbatch habilitado." & char(10) & "Hasta " & fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/microbatchSize"] & " transactions in each microbatch."
                  )

                },
                showWhen: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/microbatchSize"] > 1,
                size: "SMALL",
                color: "SECONDARY"
              )
            }
          ),
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/name"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Capacidad usada",
          value: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_107284"(
            failedCount: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"],
            maxRunning: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning"],
            runningCount: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount"]
          )
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Máximo",
          value: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning"],
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/maxRunning",
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Ejecutando",
          value: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount"],
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/runningCount",
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Encolados",
          value: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount"],
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/queuedCount",
          showWhen: local!extendedColumns,
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Fallidos",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"],
              color: if(
                fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount"] > 0,
                "NEGATIVE",
                "STANDARD"
              )
            )
          ),
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/failedCount",
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Cancelados",
          value: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/cancelledCount"],
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/cancelledCount",
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Completados",
          value: #"SYSTEM_SYSRULES_richTextDisplayField"(
            value: #"SYSTEM_SYSRULES_richTextItem_v1"(
              text: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/completedCount"],
              color: if(
                fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/completedCount"] > 0,
                "POSITIVE",
                "STANDARD"
              )
            )
          ),
          sortField: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/completedCount",
          showWhen: local!extendedColumns,
          align: "END"
        ),
        #"SYSTEM_SYSRULES_gridColumn"(
          label: "Acciones",
          value: #"SYSTEM_SYSRULES_recordActionField_v1"(
            actions: {
              #"SYSTEM_SYSRULES_recordActionItem"(
                action: #"urn:appian:record-action:v1:b3b53bd9-776c-40c2-a42b-bd112b0fd293/973c9435-98d3-4d50-ad4f-6f7d473a67eb",
                identifier: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/id"]
              ),
              #"SYSTEM_SYSRULES_recordActionItem"(
                action: #"urn:appian:record-action:v1:b3b53bd9-776c-40c2-a42b-bd112b0fd293/574297e6-128f-446e-8705-8cfe5931e9c6",
                identifier: fv!row[#"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/id"]
              )
            },
            style: "MENU_ICON"
          ),
          showWhen: #"_a-0000e470-9a48-8000-8592-01ef9001ef90_106893"(),
          align: "CENTER"
        )
      },
      initialSorts: #"SYSTEM_SYSRULES_sortInfo"(
        field: #"urn:appian:record-field:v1:bb2a66ad-ea4d-439b-afbc-703858c5c12a/name",
        ascending: true
      ),
      refreshInterval: #"_a-0000ec54-b070-8000-9bc1-011c48011c48_10966",
      refreshAlways: true,
      borderStyle: "LIGHT"
    )
  }
)
